<?php
namespace App\Service;
use App\Entity\AuditLog;use App\Entity\ChatMessage;use App\Entity\Conversation;use App\Entity\ConversationParticipant;use App\Entity\Notification;use App\Entity\User;use App\Repository\ChatMessageRepository;use App\Repository\ConversationParticipantRepository;use Doctrine\ORM\EntityManagerInterface;use LogicException;use Symfony\Component\Security\Core\Exception\AccessDeniedException;
final class ChatMessageService{public function __construct(private readonly EntityManagerInterface $em,private readonly ConversationAccessService $access,private readonly ChatMessageRepository $messages,private readonly ConversationParticipantRepository $participants,private readonly ChatEventPublisherInterface $events){}public function send(Conversation $c,User $author,string $content):ChatMessage{$this->access->assertAccess($c,$author);$m=new ChatMessage($c,$author,$content);$c->touchMessage();$this->em->persist($m);if($c->getType()===Conversation::DIRECT)$this->notifyDirect($c,$author);$this->em->flush();$this->events->publish($m);return $m;}public function edit(ChatMessage $m,User $actor,string $content):ChatMessage{$this->access->assertAccess($m->getConversation(),$actor);if(!$m->getAuthor()->getId()->equals($actor->getId()))throw new AccessDeniedException('Seul l’auteur peut modifier ce message.');$m->edit($content);$this->em->flush();$this->events->publish($m);return $m;}public function delete(ChatMessage $m,User $actor):void{$this->access->assertAccess($m->getConversation(),$actor);$own=$m->getAuthor()->getId()->equals($actor->getId());if(!$own&&!$this->access->canModerate($m->getConversation(),$actor))throw new AccessDeniedException('Suppression non autorisée.');$m->delete();if(!$own)$this->em->persist(new AuditLog($actor,AuditLog::ACTION_CHAT_MESSAGE_MODERATED,AuditLog::TARGET_TYPE_CHAT_MESSAGE,$m->getId(),'conversationId='.$m->getConversation()->getId()->toRfc4122()));$this->em->flush();$this->events->publish($m);}/** @return ChatMessage[] */public function page(Conversation $c,User $u,?ChatMessage $cursor,int $limit):array{$this->access->assertAccess($c,$u);return $this->messages->page($c,$cursor,$limit);}public function markRead(Conversation $c,User $u):void{$this->access->assertAccess($c,$u);$p=$this->participants->findFor($c,$u);if(!$p){$p=new ConversationParticipant($c,$u);$this->em->persist($p);}$p->markRead($this->messages->latest($c));$this->em->flush();}public function unread(Conversation $c,User $u):int{$this->access->assertAccess($c,$u);$p=$this->participants->findFor($c,$u);return $this->messages->countUnread($c,$p?->getLastReadAt(),$u);}private function notifyDirect(Conversation $c,User $author):void{foreach($this->participants->findForConversation($c) as $p){if($p->getUser()->getId()->equals($author->getId())||$p->isMuted())continue;$existing=$this->em->getRepository(Notification::class)->findOneBy(['user'=>$p->getUser(),'type'=>Notification::TYPE_NEW_DIRECT_MESSAGE,'targetId'=>$c->getId(),'isRead'=>false]);if($existing===null)$this->em->persist((new Notification($p->getUser(),Notification::TYPE_NEW_DIRECT_MESSAGE))->setTarget($c->getId(),Notification::TARGET_TYPE_CONVERSATION)->setActor($author)->setContent($author->getUsername().' vous a envoyé un message.'));}}}
